static PyObject* sha256_digest(PyObject* self, PyObject* args) {
    Py_buffer view;
    if (!PyArg_ParseTuple(args, "y*", &view)) {
        return NULL;
    }
    const uint8_t* data = (const uint8_t*)view.buf;
    uint64_t len = (uint64_t)view.len;

    uint32_t state[8] = {
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
        0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19
    };

    uint64_t bitlen = len * 8;
    uint64_t rem = len % 64;
    uint64_t full = len - rem;

    for (uint64_t i = 0; i < full; i += 64) {
        sha256_compress(state, data + i);
    }

    uint8_t last[128];
    memcpy(last, data + full, rem);
    last[rem] = 0x80;
    uint64_t padlen;
    if (rem < 56) {
        padlen = 56 - rem;
        memset(last + rem + 1, 0, padlen - 1);
