        for (int j = 0; j < 8; j++) {
            last[56 + j] = (uint8_t)(bitlen >> (56 - 8*j));
        }
        sha256_compress(state, last);
    } else {
        padlen = 64 - rem;
        memset(last + rem + 1, 0, padlen - 1);
        sha256_compress(state, last);
        memset(last, 0, 56);
        for (int j = 0; j < 8; j++) {
            last[56 + j] = (uint8_t)(bitlen >> (56 - 8*j));
        }
        sha256_compress(state, last);
    }

    Py_buffer_release(&view);

    PyObject* out = PyBytes_FromStringAndSize(NULL, 32);
    uint8_t* o = (uint8_t*)PyBytes_AS_STRING(out);
    for (int i = 0; i < 8; i++) {
        o[4*i]   = (uint8_t)(state[i] >> 24);
        o[4*i+1] = (uint8_t)(state[i] >> 16);
        o[4*i+2] = (uint8_t)(state[i] >> 8);
        o[4*i+3] = (uint8_t)(state[i]);
    }
    return out;
